pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));

        // Simulate token balance tracking: we'll use a simple token contract to track
        // For this test, we deploy a minimal token that tracks balances
        MockToken token = new MockToken();
        token.mint(from, v * _tos.length);

        vm.prank(from);
        token.approve(address(c), v * _tos.length);

        uint256 balanceBefore = token.balanceOf(from);

        // Execute transfer
        vm.prank(from);
        c.transfer(address(token), address(token), _tos, v);

        uint256 totalReceived = 0;
        for (uint i = 0; i < _tos.length; i++) {
            totalReceived += token.balanceOf(_tos[i]);
        }

        // The rule: total amount received by all recipients should equal v * number of recipients
        // (In the buggy version, each recipient receives 0, so totalReceived = 0)
        assertTrue(totalReceived == v * _tos.length);
    }
}

contract MockToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        require(balanceOf[from] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

