pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint256 v) public {
        // Ensure at least one recipient
        vm.assume(tos.length > 0);
        // Ensure no overflow in sum of balances (each recipient gets v at most, assume total sum fits in uint256)
        vm.assume(v <= type(uint256).max / tos.length);

        // Record balances before
        uint256[] memory before = new uint256[](tos.length);
        for (uint256 i = 0; i < tos.length; i++) {
            before[i] = tos[i].balance;
        }

        // Call transfer
        c.transfer(from, caddress, tos, v);

        // Compute total received
        uint256 totalReceived;
        for (uint256 i = 0; i < tos.length; i++) {
            totalReceived += tos[i].balance - before[i];
        }

        // The total received should equal v * tos.length
        assertTrue(totalReceived == v * tos.length);
    }
}

